    const first = Math.min(...placed.map(p => p.step));
    const atFirst = placed.filter(p => p.step === first).map(p => p.member);
    const distinct = list => list.filter((m, i) => !list.slice(0, i).some(o => _isConfigurationAlternative(index, o, m)));
